{
  "reviewer": "security",
  "findings": [
    {
      "title": "Cross-site form POST can start a maximum-size local evaluator run",
      "severity": "P2",
      "file": "cmd/email-pipeline/web_handler.go",
      "line": 108,
      "confidence": 75,
      "autofix_class": "gated_auto",
      "owner": "downstream-resolver",
      "requires_verification": true,
      "pre_existing": false,
      "exploit_failure_path": "The loopback service accepts a state-changing POST /evaluate solely from form fields. It does not validate Origin/Referer and has no CSRF token. A hostile page can submit a standard application/x-www-form-urlencoded form to http://127.0.0.1:<port>/evaluate with count=1000000 and valid fixed fields. The browser need not read the response for the request to consume the evaluator's one active slot and CPU/memory budget, blocking the legitimate local evaluator. Browser private-network protections reduce exposure in some environments but are not enforced by this server.",
      "suggested_fix": "Require a per-page CSRF token bound to a SameSite cookie for POST /evaluate and /cancel, and reject browser requests with a present Origin that is not the literal local listener origin. Preserve non-JavaScript form support by rendering the token as a hidden field.",
      "evidence": [
        "web_handler.go:108-143 accepts any POST after parsing four valid controls and begins campaign.Run without checking request origin or a CSRF token.",
        "web_input.go:58-77 permits count up to 1,000,000 and valid input is admitted into the single active-run slot.",
        "web.go:79-92 restricts TCP exposure to loopback but does not prevent a browser from issuing a cross-origin loopback form submission."
      ]
    }
  ],
  "residual_risks": [
    {
      "scope": "pre_existing",
      "risk": "None identified in the reviewed feature changes."
    },
    {
      "scope": "reviewed isolation boundary",
      "risk": "No SMTP, Redis, Asynq, distributed-ledger, or external-asset contact path was found from the web handler. The web code constructs only the deterministic generated source and calls campaign.Run with its default in-memory digest sink; web package source imports do not reference optional-service packages or CLI distributed routing."
    }
  ],
  "testing_gaps": [
    {
      "file": "cmd/email-pipeline/web_lifecycle_test.go",
      "gap": "Add an integration test that submits a valid cross-origin form POST and asserts it is rejected before source construction or campaign execution; also cover same-origin token success for both /evaluate and /cancel."
    },
    {
      "file": "internal/testinbox/smtp_mime_test.go",
      "gap": "Existing MIME tests prove text/plain versus text/html selection. Refusal-first safeguards remain intact by inspection: From/Destination reject CR/LF in config.go:111-123, the subject is fixed in smtp.go:94, generated/web input cannot control the SMTP route, and personalized body text is control-normalized plus HTML-escaped. No header/content-injection path was found."
    },
    {
      "file": "internal/distributed/task_test.go",
      "gap": "Strict payload coverage is present for unknown fields, trailing JSON, unsupported format, old missing-format text compatibility, and payload privacy. No payload-to-recipient/body/credential path or ledger identity regression was found."
    },
    {
      "commands_run": [
        "go test -count=1 ./cmd/email-pipeline ./internal/campaign ./internal/distributed ./internal/testinbox"
      ],
      "result": "Passed."
    }
  ]
}

{
  "reviewer": "api-contract",
  "findings": [
    {
      "title": "Server-Timing and page request duration are captured before the final response body is ready",
      "severity": "P2",
      "file": "cmd/email-pipeline/web_handler.go",
      "line": 162,
      "confidence": 100,
      "scenario": "For an HTML or HTMX evaluation response, the handler renders once to probe for template errors, records requestDuration, then renders the final body again at line 164. Any time spent producing that final body is excluded from both Server-Timing and the displayed total duration, despite the documented contract that timing ends when response data is ready. Template growth or a slow template helper will therefore silently under-report the browser evidence timing.",
      "minimal_fix": "Construct the final representation before taking the end timestamp, then set Server-Timing from that timestamp. If the rendered page must display the same duration, use a representation that can be finalized without a second template-render pass (for example, render the timing field separately or use a fixed placeholder).",
      "autofix_class": "gated_auto",
      "owner": "downstream-resolver",
      "requires_verification": true,
      "pre_existing": false
    }
  ],
  "residual_risks": [
    {
      "type": "release_rollout_advisory",
      "detail": "The code and README correctly preserve payload version 1, omit default text format, and decode missing format as text. Explicit HTML payloads remain intentionally incompatible with old strict workers. This is not a code defect in this change; deployment must remain worker-first, and HTML-aware workers must stay online until all HTML tasks are terminal."
    },
    {
      "type": "compatibility_review",
      "detail": "No breaking persisted-task, report-body, task-ID, queue-name, ledger-identity, or old text SMTP MIME contract was found. The new CLI --format flag defaults to text; old task JSON decodes as text; default task serialization stays byte-compatible through omitempty."
    }
  ],
  "testing_gaps": [
    {
      "file": "cmd/email-pipeline/web_lifecycle_test.go",
      "detail": "Timing coverage confirms a mocked duration value but does not demonstrate that duration is measured after final HTML/HTMX response construction. Add a controlled final-render seam or deliberately expensive template helper and assert Server-Timing includes that work."
    },
    {
      "file": "cmd/email-pipeline/web_template_test.go",
      "detail": "The requested format check reports this untracked test file as not gofmt-formatted. This is not an API-contract finding, but the feature does not currently satisfy the repository formatting gate."
    },
    {
      "scope": "HTTP response writer failures",
      "detail": "Response writes are intentionally ignored in evaluate, preview, and writePage. Lifecycle cleanup is protected by defer in evaluate, but there is no focused test documenting behavior when a ResponseWriter returns an error. No consumer-visible contract break was established from this alone."
    }
  ]
}
